    color: var(--color-text);
    line-height: 1.6;
}

/* Skip link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--color-primary);
    color: white;
    padding: 0.5rem 1rem;
    z-index: 1000;
    transition: top 0.3s;
}
.skip-link:focus { top: 0; }

/* Header */
.header {
    position: sticky;
    top: 0;
    z-index: 100;
    background-color: rgba(15, 15, 26, 0.95);
    backdrop-filter: blur(8px);
}

.header__nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 1rem 1.5rem;
}

.header__brand {
    color: var(--color-primary);
    text-decoration: none;
    font-weight: 700;
    font-size: 1.25rem;
}

.header__links {
    display: flex;
    list-style: none;
    gap: 1.5rem;
}

.header__link {
    color: var(--color-text-muted);
    text-decoration: none;
    font-size: 0.95rem;
    transition: color 0.3s ease;
}

.header__link:hover { color: var(--color-primary); }

/* Hero */
.hero {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    text-align: center;
    min-height: 90vh;
    padding: 2rem 1.5rem;
}

.hero__title {
    font-size: clamp(2rem, 6vw, 3.5rem);
    color: var(--color-heading);
    margin-bottom: 1rem;
}

.hero__name { color: var(--color-primary); }

.hero__subtitle {
    font-size: clamp(1rem, 2.5vw, 1.3rem);
    color: var(--color-text-muted);
    margin-bottom: 2rem;
    max-width: 600px;
}

.hero__cta {
    display: inline-block;
    background-color: var(--color-primary);
    color: white;
    padding: 0.9rem 2rem;
    border-radius: 6px;
    text-decoration: none;
    font-weight: 600;
    transition: background-color 0.3s ease, transform 0.2s ease;
}

.hero__cta:hover {
    background-color: var(--color-primary-dark);
    transform: translateY(-2px);
}

/* Features */
.features {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: var(--spacing-section) 1.5rem;
}

.features__heading {
    text-align: center;
    font-size: clamp(1.5rem, 3vw, 2rem);
    color: var(--color-heading);
    margin-bottom: 2rem;
}

.features__grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1.5rem;
}

.feature-card {
    background-color: var(--color-surface);
    padding: 2rem;
    border-radius: 8px;
    border-top: 3px solid var(--color-primary);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.feature-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 24px rgba(233, 69, 96, 0.15);
}

.feature-card__title {
    color: var(--color-primary);
    margin-bottom: 0.75rem;
}

/* About */
.about {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: var(--spacing-section) 1.5rem;
}

.about__heading {
    text-align: center;
    font-size: clamp(1.5rem, 3vw, 2rem);
    color: var(--color-heading);
    margin-bottom: 2rem;
}

.about__content {
    display: flex;
    gap: 2rem;
    align-items: center;
}

.about__image {
    width: 200px;
    height: 200px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid var(--color-primary);
    flex-shrink: 0;
}

.about__text p + p { margin-top: 1rem; }

/* Projects */
.projects {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: var(--spacing-section) 1.5rem;
}

.projects__heading {
    text-align: center;
    font-size: clamp(1.5rem, 3vw, 2rem);
    color: var(--color-heading);
    margin-bottom: 2rem;
}

.projects__grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 1.5rem;
}

.project-card {
    background-color: var(--color-surface);
    padding: 2rem;
    border-radius: 8px;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    transition: transform 0.3s ease;
}

.project-card:hover { transform: translateY(-4px); }

.project-card__title { color: var(--color-heading); }

.project-card__link {
    color: var(--color-primary);
    text-decoration: none;
    font-weight: 600;
    margin-top: auto;
    transition: color 0.3s ease;
}

.project-card__link:hover { color: var(--color-primary-dark); }

/* Contact */
.contact {
    text-align: center;
    padding: var(--spacing-section) 1.5rem;
}

.contact__heading {
    font-size: clamp(1.5rem, 3vw, 2rem);
    color: var(--color-heading);
    margin-bottom: 1rem;
}

.contact__text { margin-bottom: 2rem; color: var(--color-text-muted); }

.contact__cta {
    display: inline-block;
    background-color: var(--color-primary);
    color: white;
    padding: 0.9rem 2rem;
    border-radius: 6px;
    text-decoration: none;
    font-weight: 600;
    transition: background-color 0.3s ease, transform 0.2s ease;
}

.contact__cta:hover {
    background-color: var(--color-primary-dark);
    transform: translateY(-2px);
}

/* Footer */
.footer {
    text-align: center;
    padding: 2rem 1.5rem;
    background-color: var(--color-surface);
    color: var(--color-text-muted);
    font-size: 0.9rem;
}

/* Responsive */
@media (max-width: 767px) {
    .header__nav {
        flex-direction: column;
        gap: 0.75rem;
    }
    .header__links { gap: 1rem; }
    .about__content {
        flex-direction: column;
        text-align: center;
    }
}

/* Focus styles */
a:focus,
button:focus {
    outline: 2px solid var(--color-primary);
    outline-offset: 2px;
}

/* Reduced motion preference */
@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        animation-duration: 0.01ms !important;
        transition-duration: 0.01ms !important;
    }
}

