function memoryStore() {
  let rows = [];
  return {
    insert: function (doc) {
      rows.push(doc);
    },
    all: function () {
      return rows.slice();
    },
    restart: function () {
      rows = [];
    }
  };
}

function diskStore() {
  const rows = [];
  let seq = 0;
  return {
    insert: function (doc) {
      const copy = {};
      Object.keys(doc).forEach(function (key) {
        copy[key] = doc[key];
      });
      seq += 1;
      copy._id = 'id-' + seq;
      rows.push(copy);
      return copy;
    },
    all: function () {
      return rows.slice();
    },
    restartProcess: function () {
      return rows.length;
    }
  };
}

