import { Service, inject, signal } from "@angular/core";
import { HttpClient } from "@angular/common/http";
import { firstValueFrom } from "rxjs";
import { environment } from "../environments/environment";
import { Todo } from "./types";

@Service()
export class TodoService {
  private http = inject(HttpClient);

  // URL of the API
  readonly url = environment.apiUrl;

  // the list of todos, as a signal
  readonly todos = signal<Todo[]>([]);

  constructor() {
    // load the list when the service is first created
    this.getTodos();
  }

  async getTodos() {
    const data = await firstValueFrom(this.http.get<Todo[]>(this.url));
    this.todos.set(data);
    return data;
  }

  async createTodo(todo: Todo) {
    await firstValueFrom(this.http.post<Todo>(this.url, todo));
    return this.getTodos();
  }

  async updateTodo(todo: Todo) {
    await firstValueFrom(this.http.put<Todo>(`${this.url}${todo.id}/`, todo));
    return this.getTodos();
  }

  async deleteTodo(todo: Todo) {
    await firstValueFrom(this.http.delete(`${this.url}${todo.id}/`));
    return this.getTodos();
  }
}

