  let track = 0;
  return {
    next() {
      while (disc < discs.length) {
        const songs = discs[disc];
        if (track < songs.length) {
          const song = songs[track];
          track += 1;
          return { value: song, done: false };
        }
        disc += 1;
        track = 0;
      }
      return { value: undefined, done: true };
    },
  };
