function redact(fields) {
  const secretKey = /^(password|token|authorization|cookie)$/i;
  const out = {};
  for (const [key, value] of Object.entries(fields)) {
    out[key] = secretKey.test(key) ? '[REDACTED]' : cleanString(value);
  }
  return out;
}

